// Byte-preserving PNG encoder. Canvas premultiplication can damage packed data
// when the alpha channel contains height rather than opacity.
const table=Uint32Array.from({length:256},(_,i)=>{let c=i;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;return c>>>0;});
const crc=bytes=>{let c=0xffffffff;for(const b of bytes)c=table[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0;};
function chunk(name,data){const type=new TextEncoder().encode(name),out=new Uint8Array(data.length+12),view=new DataView(out.buffer);view.setUint32(0,data.length);out.set(type,4);out.set(data,8);view.setUint32(out.length-4,crc(out.subarray(4,out.length-4)));return out;}
export async function rgbaPNG(data,width,height){if(!Number.isInteger(width)||!Number.isInteger(height)||width<1||height<1||data.length!==width*height*4)throw Error('Invalid PNG pixel buffer');const rows=new Uint8Array(height*(width*4+1));for(let y=0;y<height;y++)rows.set(data.subarray(y*width*4,(y+1)*width*4),y*(width*4+1)+1);const compressed=new Uint8Array(await new Response(new Blob([rows]).stream().pipeThrough(new CompressionStream('deflate'))).arrayBuffer()),header=new Uint8Array(13),h=new DataView(header.buffer);h.setUint32(0,width);h.setUint32(4,height);header[8]=8;header[9]=6;return new Blob([new Uint8Array([137,80,78,71,13,10,26,10]),chunk('IHDR',header),chunk('IDAT',compressed),chunk('IEND',new Uint8Array())],{type:'image/png'});}
